input.query:
SELECT COUNT(DISTINCT Ensembl) AS cd_in_universe FROM proteinatlas WHERE "Protein class" LIKE '%CD markers%';
SELECT COUNT(*) AS cd_in_sample FROM (SELECT DISTINCT "ENSG ID" AS e FROM rna_immune_cell_sample WHERE "Immune cell"='NK-cell') s JOIN proteinatlas p ON s.e=p.Ensembl WHERE p."Protein class" LIKE '%CD markers%';
SELECT DISTINCT "Immune cell" FROM rna_immune_cell WHERE "Immune cell" IN ('NK-cell','memory CD8 T-cell');
